INSERT INTO `sesiones` VALUES (1,'Bienvenida al programa','Conoce cómo funciona el programa Destino Au Pair y qué vas a aprender.','https://www.youtube.com/watch?v=LvpbGY2Y6v4',1,1,NULL,'eVealhAFxPs',2,'Bienvenida','Publicada',NULL),(2,'La realidad de ser Au Pair','Descubre qué significa realmente ser Au Pair, qué incluye el programa y lo que\nmuchas personas no saben antes de comenzar.','https://www.youtube.com/watch?v=GiWS2tFW11E',2,1,'1A10la9gUOAJEm9Ijhn-LdcFNttppm9tc',NULL,3,'Modulo 1','Publicada',NULL),(3,'¿Cumples con los requisitos para aplicar?','Conoce los requisitos oficiales, cómo prepararte mejor y descubre si este programa\nrealmente es para ti.','',3,1,'1qxRygCh-7fhvvJu6b__wdBwU00Xsik4G',NULL,3,'Modulo 2','Publicada',NULL),(4,'Cómo crear un perfil que conecte','Aprende qué buscan las familias, evita errores comunes y descubre cómo construir\nun perfil fuerte y auténtico.','',4,1,'1rF7GDg17RSU_0pE6cVVx0e-1XlWv5Hih',NULL,2,'Modulo 3','Publicada',NULL),(5,'Entrevistas, familias y proceso de match','Entiende cómo funciona el match con familias, cómo prepararte para entrevistas y\nqué hacer para generar conexión.','',5,1,'1PujXSY_jxAW5uQThpnpay0Y01y_xY0bv',NULL,2,'Modulo 4','Publicada',NULL),(6,'Costos, pagos y beneficios del programa','Conoce cuánto cuesta el proceso, los gastos adicionales y cómo funcionan los\nbeneficios económicos disponibles.','',6,1,'1vVPvTmqJxvZTmkBUyaPsdN8VqCJb7oDt',NULL,3,'Modulo 5','Publicada',NULL),(7,'Cómo avanzar correctamente en tu proceso','Descubre cómo empezar con la agencia, cómo funciona el tiempo del proceso y\ncuándo dar el siguiente paso.','',7,1,'1ISMUneF_mM47RMgBQpTupZnd9_UsVAA_',NULL,2,'Modulo 6','Publicada',NULL),(8,'Tu siguiente paso comienza aquí','Cómo adaptarte, comunicarte con tu familia y tener éxito.','Haz un cierre consciente de tu preparación y descubre cómo continuar hacia tu aplicación oficial.',8,1,'1UfOE7vePaFQHFI59dTkRxf6Dtj0Lt9k8',NULL,2,'Modulo 7','Publicada',NULL);
