  `confirmado_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_ventas_usuario` (`usuario_id`),
  KEY `idx_ventas_estado` (`estado`),
  KEY `idx_ventas_codigo` (`codigo_promo_id`),
